# compounds GPT-2 xl — batch 1024, lr 1.01e-03
# The compounds batch-size grid of the 2026-11-19c directive. Generated by
# scripts/compounds_batch_sweep_configs.py from the derived arm inventory; edit the
# inventory and regenerate rather than editing this file.
#
# This arm's place in the grid. GPT-2 runs one rate per batch (§3), so this is the whole of xl at batch 1024.
#
# The budget is fixed in columns, not in steps (§2): 11,980,800 packed blocks of
# 1024 tokens = 12,268,339,200 tokens, the same for all 16 GPT-2
# arms. At batch 1024 that is 11,700 iterations, so the four batches cover the
# same data and their curves are compared at the same column.
#
# The rate is this size's 2,560 rate scaled by sqrt(batch/2560) (§3): 1.0 x sqrt(1024/2560) x this size's 2,560 rate = 1.01e-03.
#
# Warmup is 2 % of this arm's own length (§4), truncated: 234 of
# 11,700. The decay shape is the one the existing ladder uses.
#
# One GPU takes 4 columns and the accumulation count carries the rest (§8):
# 4 x 256 = 1024. Held across the four batches, so what differs between them is the accumulation count and nothing else.
#
# The validation set is deterministic already (§6), so nothing about the evaluation
# changes for the GPT-2 arms: the same fixed 3,200 val sequences every
# time, drawn from a constant inside train.py rather than from the run's seed. The
# existing 2,560 GPT-2 numbers therefore stand beside this grid without a re-measure.
#
# The judged metric is val_loss (§7).

from molcrawl.data.compounds.utils.tokenizer import CompoundsTokenizer as Tokenizer
from molcrawl.core.paths import COMPOUNDS_DATASET_DIR_GPT2, get_gpt2_output_path

dataset_dir = COMPOUNDS_DATASET_DIR_GPT2

tensorboard = True  # log training metrics to tensorboard
tensorboard_dir = get_gpt2_output_path("compounds", "xl") + "-b1024-lr1p01e3"
out_dir = get_gpt2_output_path("compounds", "xl") + "-b1024-lr1p01e3"

tokenizer = Tokenizer("assets/molecules/vocab.txt", 256)
meta_vocab_size = tokenizer.vocab_size
eos_token_id = tokenizer.eos_token_id  # 13 ([SEP]) — the molecule separator

# nanoGPT divides gradient_accumulation_steps by the DDP world size, so the effective
# global batch = batch_size * gradient_accumulation_steps and is GPU-count-independent.
# 4 * 256 = 1024 (§8).
batch_size = 4
block_size = 1024
gradient_accumulation_steps = 256

# train.py refuses to start when micro x accumulation disagrees with this (§5).
expected_global_batch = 1024

max_iters = 11700
# Both placed per arm (§4): the decay runs the length of this arm, and the floor is a
# tenth of this arm's own peak.
lr_decay_iters = 11700
min_lr = 0.000101
warmup_iters = 234  # 2 % of max_iters (§4)
learning_rate = 0.00101

# 292 evaluation points, at the same column positions as every other batch
# in the grid (§2). The training loss is logged 8 times per evaluation
# window, so every validation point has a training point at the same column.
eval_interval = 40
log_interval = 5
# Fix the number of val *sequences* rather than batches, so sizes whose batch_size
# differs still average over the same sample. train.py derives eval_iters from this
# and batch_size, so setting eval_iters here too would be dead config.
eval_sequences = 3200
deterministic_val_eval = True

init_from = "scratch"

# Checkpoint policy. The interval is five evaluation windows, which puts the
# opportunities at the same column positions across the four batches.
always_save_checkpoint = False
save_checkpoint_steps = 200
max_checkpoints = 10

# Pretraining runs the whole schedule (§4).
early_stopping = False

weight_decay = 0.1

dataset = "compounds"

# Special Tokens
start_instruction = 12
eos_token = 12  # eos

dataset_params = {"dataset_dir": dataset_dir}

# seed 42 per the standing directive (§9).
seed = 42
